from datetime import date, timedelta
import calendar

_WD = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _nth_weekday(year: int, month: int, n: int, wd: int) -> date | None:
    if n == -1:
        last = date(year, month, calendar.monthrange(year, month)[1])
        return last - timedelta(days=(last.weekday() - wd) % 7)
    first = date(year, month, 1)
    dt = first + timedelta(days=(wd - first.weekday()) % 7 + (n - 1) * 7)
    if dt.month != month:
        return None
    return dt


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = (int(p) for p in start.split("-"))
    start_date = date(y, m, d)
    parts = rule.split(" ")
    kind = parts[0]
    k = int(parts[1])
    out: list[str] = []

    if kind == "DAILY":
        cur = start_date
        for _ in range(count):
            out.append(cur.isoformat())
            cur += timedelta(days=k)
        return out

    if kind == "WEEKLY":
        wanted = sorted(_WD[code] for code in parts[2].split(","))
        monday = start_date - timedelta(days=start_date.weekday())
        week = 0
        while len(out) < count:
            for wd in wanted:
                dt = monday + timedelta(days=week * 7 + wd)
                if dt >= start_date:
                    out.append(dt.isoformat())
                    if len(out) == count:
                        return out
            week += k
        return out

    if kind == "MONTHLY":
        year0, month0 = start_date.year, start_date.month
        idx = 0
        if len(parts) == 3:
            dom = int(parts[2])
            while len(out) < count:
                yy = year0 + (month0 - 1 + idx) // 12
                mm = (month0 - 1 + idx) % 12 + 1
                last = calendar.monthrange(yy, mm)[1]
                if dom == -1 or dom <= last:
                    dd = last if dom == -1 else dom
                    dt = date(yy, mm, dd)
                    if dt >= start_date:
                        out.append(dt.isoformat())
                idx += k
            return out
        nth = int(parts[2])
        wd = _WD[parts[3]]
        while len(out) < count:
            yy = year0 + (month0 - 1 + idx) // 12
            mm = (month0 - 1 + idx) % 12 + 1
            dt = _nth_weekday(yy, mm, nth, wd)
            if dt is not None and dt >= start_date:
                out.append(dt.isoformat())
            idx += k
        return out

    mm_s, dd_s = parts[2].split("-")
    mm, dd = int(mm_s), int(dd_s)
    year = start_date.year
    while len(out) < count:
        try:
            dt = date(year, mm, dd)
        except ValueError:
            dt = None
        if dt is not None and dt >= start_date:
            out.append(dt.isoformat())
        year += k
    return out
